package com.digitalhealth.controller; import com.digitalhealth.dto.NotificationDTO; import com.digitalhealth.security.AccessService; import com.digitalhealth.service.NotificationService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/workers/{workerId}/notifications") @CrossOrigin(originPatterns={"http://localhost:*","http://127.0.0.1:*"}) public class NotificationController {private final NotificationService service;private final AccessService access;public NotificationController(NotificationService s,AccessService a){service=s;access=a;}@GetMapping public List<NotificationDTO> list(@PathVariable Long workerId){access.workerOrAdmin(workerId);return service.list(workerId);}@PatchMapping("/{id}/read") public NotificationDTO read(@PathVariable Long workerId,@PathVariable Long id){access.workerOrAdmin(workerId);return service.read(workerId,id);}}
